// Rows read before/after: the REAL SQL generated by functions/_lib/sb.js for the client's requests is run through
// EXPLAIN QUERY PLAN on a SQLite database loaded with the real snapshot data, without and with cloudflare/migrations/0002_read_indexes.sql.
import test from 'node:test';
import assert from 'node:assert/strict';
import { newDb, mockD1, loadSb, rowsRead } from './helpers.mjs';

const TABLES = ['travel_questions', 'exam_questions', 'quiz_questions', 'drugs', 'applied_pharm_items', 'dialysis_topics', 'articles', 'course_questions', 'course_chapters'];
const before = newDb({ tables: TABLES });
const after = newDb({ migrate0002: true, tables: TABLES });
const { handleRest } = await loadSb();

/** SQL statements sb.js would send to D1 for one client request. */
async function sqlOf(method, path, headers = {}) {
  const d1 = mockD1(before.db);
  const [table, ...qs] = path.split('?');
  await handleRest(new Request(`https://x.test/rest/v1/${path}`, { method, headers }), { DB: d1 }, [table]);
  return d1.log.map((q) => ({ sql: q.sql, params: q.params }));
}
const sum = (db, stmts) => stmts.reduce((a, s) => a + rowsRead(db.db, s.sql, s.params).reads, 0);
const plans = (db, stmts) => stmts.map((s) => rowsRead(db.db, s.sql, s.params));
const report = [];
const note = (name, b, a) => { report.push({ name, before: b, after: a }); };

const cats = Object.keys(JSON.parse(await import('node:fs').then((f) => f.readFileSync(new URL('../../public/data/travel_counts.json', import.meta.url), 'utf8'))));
const examId = before.db.prepare("SELECT exam_id e FROM exam_questions GROUP BY exam_id ORDER BY COUNT(*) DESC LIMIT 1").get().e;
const slug = before.db.prepare('SELECT slug s FROM drugs LIMIT 1').get().s;
const artId = before.db.prepare('SELECT article_id a FROM quiz_questions LIMIT 1').get().a;
const topicId = before.db.prepare('SELECT id FROM dialysis_topics LIMIT 1').get().id;

test('topic page: primary-key read instead of the whole section table', async () => {
  const old = await sqlOf('GET', 'dialysis_topics?select=*&order=order_num.asc');
  const neu = await sqlOf('GET', `dialysis_topics?select=*&id=eq.${topicId}`);
  const b = sum(before, old), a = sum(after, neu);
  note('Topic page (dialysis, 17-row table)', b, a);
  assert.match(plans(after, neu)[0].plan, /SEARCH .*PRIMARY KEY|SEARCH .*INDEX/);
  assert.equal(a, 1); assert.ok(a < b);
});

test('travel_questions: per-category counts, category page and search index', async () => {
  // OLD hub: one HEAD count per category (sb.js runs the SELECT and the COUNT for each)
  const oldCounts = [];
  for (const c of cats) oldCounts.push(...(await sqlOf('HEAD', `travel_questions?select=id&category_id=eq.${c}`, { prefer: 'count=exact' })));
  const countSql = [{ sql: 'SELECT category_id, COUNT(*) n FROM travel_questions GROUP BY category_id', params: [] }]; // new RPC
  note(`Travel hub counts (${cats.length} categories)`, sum(before, oldCounts), sum(after, countSql));
  assert.match(plans(after, countSql)[0].plan, /INDEX idx_travel_q_cat_order/);

  // category page (largest category): old 1,000-row pages vs one 5,000-row page
  const big = before.db.prepare('SELECT category_id c, COUNT(*) n FROM travel_questions GROUP BY 1 ORDER BY 2 DESC LIMIT 1').get();
  const oldPages = [];
  for (let off = 0; off < big.n; off += 1000) oldPages.push(...(await sqlOf('GET', `travel_questions?select=*&order=order_num.asc&order=id.asc&offset=${off}&limit=1000&category_id=eq.${big.c}`)));
  const newPage = await sqlOf('GET', `travel_questions?select=*&order=order_num.asc&order=id.asc&offset=0&limit=5000&category_id=eq.${big.c}`);
  note(`Travel category page (${big.c}, ${big.n} questions)`, sum(before, oldPages), sum(after, newPage));
  assert.match(plans(after, newPage)[0].plan, /idx_travel_q_cat_order/);

  // search index: 10 sorted 1,000-row chunks of the whole table vs the static file (no D1 query)
  const total = before.counts.travel_questions;
  const chunks = [];
  for (let off = 0; off < total; off += 1000) chunks.push(...(await sqlOf('GET', `travel_questions?select=id,category_id,question_en,question_ar&order=order_num.asc&order=id.asc&offset=${off}&limit=1000`)));
  note(`Search index: travel_questions lite (${total} rows, ${chunks.length} queries)`, sum(before, chunks), 0);
  assert.ok(sum(before, chunks) >= total * Math.floor(total / 1000));
});

test('exam page, quiz widgets, drug slug, applied pharmacology: SEARCH on the new indexes', async () => {
  const exam = await sqlOf('GET', `exam_questions?select=*&exam_id=eq.${examId}&order=order_num.asc`);
  note(`Exam page (${examId})`, sum(before, exam), sum(after, exam));
  assert.match(plans(after, exam)[0].plan, /idx_exam_q_exam_order/);

  const q = `quiz_questions?select=*&article_id=eq.${artId}&type=eq.mcq&lang=eq.ar&order=order_index.asc`;
  const slugQ = 'articles?select=id&slug=eq.' + before.db.prepare('SELECT slug FROM articles LIMIT 1').get().slug;
  const old3 = [...(await sqlOf('GET', slugQ)), ...(await sqlOf('GET', q)), ...(await sqlOf('GET', slugQ)), ...(await sqlOf('GET', q)), ...(await sqlOf('GET', slugQ)), ...(await sqlOf('GET', q))];
  const new3 = [...(await sqlOf('GET', slugQ)), ...(await sqlOf('GET', q)), ...(await sqlOf('GET', q)), ...(await sqlOf('GET', q))]; // one shared slug lookup
  note('Article with 3 quiz widgets', sum(before, old3), sum(after, new3));
  assert.match(plans(after, await sqlOf('GET', q))[0].plan, /idx_quiz_q_article/);

  const drug = await sqlOf('GET', `drugs?select=id&slug=eq.${slug}&limit=1`);
  note('Drug page existence check (edge function)', sum(before, drug), sum(after, drug));
  assert.match(plans(after, drug)[0].plan, /idx_drugs_slug/);

  const ap = await sqlOf('GET', 'applied_pharm_items?select=*&order=order_num.asc&part=eq.1');
  note('Applied pharmacology part 1 (uncached DB cost)', sum(before, ap), sum(after, ap));
  assert.match(plans(after, ap)[0].plan, /idx_applied_pharm_part_order/);

  const course = await sqlOf('GET', 'course_questions?select=*&order=order_num.asc&order=id.asc&offset=0&limit=1000&course_id=eq.acls');
  note('Course quiz (acls)', sum(before, course), sum(after, course));
  assert.match(plans(after, course)[0].plan, /idx_course_q_course_order/);
});

test('presence ping de-duplication uses the visitor index (synthetic pings: 100 online visitors, ~4 pings each inside the window)', async () => {
  for (const { db } of [before, after]) {
    db.exec('DELETE FROM site_pings');
    const ins = db.prepare("INSERT INTO site_pings (visitor_id, created_at) VALUES (?, strftime('%Y-%m-%dT%H:%M:%fZ','now', ?))");
    db.exec('BEGIN');
    for (let v = 0; v < 100; v++) for (let k = 0; k < 4; k++) ins.run(`visitor-${v}`, `-${v + k * 30} seconds`);
    db.exec('COMMIT');
  }
  // A visitor with no ping in the window (the normal case: it is the ping that will be stored). Before the index the query walks every
  // ping of the window (idx created_at range) looking for that visitor; with idx (visitor_id, created_at) it probes only that visitor.
  const dedupe = "SELECT 1 FROM site_pings WHERE visitor_id = ? AND created_at > datetime('now','-150 seconds') LIMIT 1";
  const plan = (db) => db.prepare(`EXPLAIN QUERY PLAN ${dedupe}`).all('visitor-new').map((r) => r.detail).join(' | ');
  assert.match(plan(before.db), /idx_site_pings_created/);
  assert.match(plan(after.db), /idx_site_pings_visitor/);
  const win = before.db.prepare("SELECT COUNT(*) n FROM site_pings WHERE created_at > datetime('now','-150 seconds')").get().n;
  const own = after.db.prepare("SELECT COUNT(*) n FROM site_pings WHERE visitor_id = ? AND created_at > datetime('now','-150 seconds')").get('visitor-new').n;
  note('Presence ping de-dup (synthetic, 100 online visitors)', win, own);
});

test('summary: every measured case reads fewer rows after the change', () => {
  const fmt = (n) => n.toLocaleString('en-US');
  console.log('\n  rows read (estimate) — before -> after');
  for (const r of report) console.log(`  ${r.name.padEnd(62)} ${fmt(r.before).padStart(9)} -> ${fmt(r.after).padStart(7)}`);
  for (const r of report) assert.ok(r.after <= r.before, r.name);
  assert.ok(report.some((r) => r.before / Math.max(1, r.after) > 20));
});
